@Composable fun TaskWorkspace(repository:ClientRepository,projectId:String){
 key(projectId,repository.accountId){TaskWorkspaceContent(repository,projectId)}
}
@Composable private fun TaskWorkspaceContent(repository:ClientRepository,projectId:String){
 val base=twBase(projectId);var refresh by remember{mutableIntStateOf(0)};var selected by rememberSaveable{mutableStateOf<String?>(null)};var create by rememberSaveable{mutableStateOf(false)};var planning by rememberSaveable{mutableStateOf(false)}
 var graph by remember{mutableStateOf<JsonObject?>(null)};var me by remember{mutableStateOf<JsonObject?>(null)};var members by remember{mutableStateOf<List<JsonObject>>(emptyList())};var error by remember{mutableStateOf<String?>(null)}
 LaunchedEffect(projectId,repository.accountId,refresh){try{me=repository.get("$base/members/me");graph=repository.get("$base/tasks/graph");members=taskWorkspaceMembers(repository,base);error=null}catch(e:CancellationException){throw e}catch(e:Exception){error=e.message}}
 BackHandler(selected!=null||create||planning){selected=null;create=false;planning=false}
 Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){
  Text("任务协作",style=MaterialTheme.typography.headlineSmall);error?.let{Text(it,color=MaterialTheme.colorScheme.error)}
  if(selected!=null){TextButton({selected=null}){Text("返回任务列表")};TaskWorkspaceDetail(repository,projectId,selected!!,graph,me,members,refresh){refresh++};return@Column}
  if(planning){TextButton({planning=false}){Text("返回任务列表")};if(graph!=null&&me!=null)TaskWorkspacePlanning(repository,base,graph!!,me!!,members){refresh++};return@Column}
  if(create){TextButton({create=false}){Text("返回任务列表")};if(graph!=null)TaskWorkspaceEditor(repository,base,null,graph!!,members){create=false;refresh++};return@Column}
  OutlinedButton({planning=true}){Text("AI 拆解、调整与分工")};Text("前置依赖用于提示，可以提前领取、执行和提交。",style=MaterialTheme.typography.bodySmall)
  graph?.get("totals")?.jsonObject?.let{Text("共 ${it.twText("total")} 项 · 已完成 ${it.twText("done")} 项")}
  TextButton({refresh++}){Text("刷新任务与权限")};if(me?.twCan("taskManage")==true)Button({create=true},enabled=graph!=null){Text("新建任务")}
  var query by rememberSaveable{mutableStateOf("")};var applied by rememberSaveable{mutableStateOf("")};var filter by rememberSaveable{mutableStateOf("")};var mine by rememberSaveable{mutableStateOf(false)}
  TaskWorkspaceField("搜索任务",query,{query=it},200);OutlinedButton({applied=query.trim()}){Text("搜索")}
  TaskWorkspaceChoice("任务状态",listOf("" to "全部","open" to "待领取","in_progress" to "执行中","submitted" to "待验收","accepted" to "已完成","pending" to "待人工审核","improve" to "需改进","rework" to "需重做"),filter){filter=it}
  Row{Checkbox(mine,{mine=it});Text("只看分配给我的任务",Modifier.padding(top=12.dp))}
  val filters="?limit=50&q=${Uri.encode(applied)}"+(if(filter=="pending")"&pendingReview=true"else if(filter.isNotEmpty())"&lifecycleState=$filter"else"")+(if(mine&&repository.accountId!=null)"&assigneeId=${Uri.encode(repository.accountId)}"else"")
  TaskWorkspacePage(repository,"$base/tasks$filters",refresh){rows->if(rows.isEmpty())Text("当前筛选下没有任务");rows.forEach{task->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text(task.twText("title"),style=MaterialTheme.typography.titleMedium);Text(twState(task));Text("负责人："+(members.firstOrNull{it.twText("userId")==task.twText("assigneeId")}?.twText("displayName")?:"未分配"));if(task.twText("dueDate").isNotEmpty())Text("期限：${task.twText("dueDate")}");TaskWorkspaceDependencies(task,graph?.twRows().orEmpty());OutlinedButton({selected=task.twText("taskId")}){Text("查看与处理")}}}}}
 }
}
internal suspend fun taskWorkspaceMembers(repository:ClientRepository,base:String):List<JsonObject>{
 val all=mutableListOf<JsonObject>();var cursor:String?=null;val seen=mutableSetOf<String>();val owner=repository.accountId;val epoch=repository.epoch
 do{val page=repository.get("$base/members?limit=100"+(cursor?.let{"&cursor=${Uri.encode(it)}"}?:""));check(owner==repository.accountId&&epoch==repository.epoch){"账户已变化"};all+=page.twRows();cursor=page.twText("nextCursor").takeIf{it.isNotBlank()};check(cursor==null||seen.add(cursor)){"成员分页游标重复"}}while(cursor!=null)
 return all.distinctBy{it.twText("userId")}
}
@Composable internal fun TaskWorkspaceChoice(label:String,choices:List<Pair<String,String>>,value:String,onChange:(String)->Unit){var open by remember{mutableStateOf(false)};OutlinedButton({open=!open}){Text("$label：${choices.firstOrNull{it.first==value}?.second.orEmpty()}")};if(open)choices.forEach{(id,name)->TextButton({onChange(id);open=false}){Text(name)}}}
@Composable private fun TaskWorkspaceDependencies(task:JsonObject,tasks:List<JsonObject>){val ids=task.twIds("dependsOnTaskIds");val unfinished=task.twIds("unfinishedDependencyIds").toSet();if(ids.isNotEmpty()){Text("前置任务",style=MaterialTheme.typography.labelLarge);ids.forEach{id->Text("• ${tasks.firstOrNull{it.twText("taskId")==id}?.twText("title")?:"暂不可见的任务"}"+if(id in unfinished)"（尚未完成）"else"（已完成）")}}}

@Composable private fun TaskWorkspaceEditor(repository:ClientRepository,base:String,task:JsonObject?,graph:JsonObject,members:List<JsonObject>,onSaved:()->Unit){
 val identity=task?.twText("taskId")?:"new"
 var baseRevision by rememberSaveable(identity){mutableIntStateOf(task?.let{twRevision(it)}?:1)};var graphRevision by rememberSaveable(identity){mutableIntStateOf(graph["graphRevision"]!!.jsonPrimitive.int)};val draftStore=remember(repository){NativeDraftStore(repository)};val draftKey="task-editor:$base:$identity";var loaded by remember(identity){mutableStateOf(false)};var persistenceError by remember{mutableStateOf<String?>(null)}
 var title by rememberSaveable(identity){mutableStateOf(task?.twText("title").orEmpty())};var detail by rememberSaveable(identity){mutableStateOf(task?.twText("detail").orEmpty())};var criteria by rememberSaveable(identity){mutableStateOf(task?.twText("criteria").orEmpty())};var effort by rememberSaveable(identity){mutableStateOf(task?.twText("effortHours")?:"1")};var due by rememberSaveable(identity){mutableStateOf(task?.twText("dueDate").orEmpty())};var assignee by rememberSaveable(identity){mutableStateOf<String?>(null)};var dependencies by remember(identity){mutableStateOf(task?.twIds("dependsOnTaskIds").orEmpty())}
 LaunchedEffect(identity,repository.accountId){try{draftStore.read(draftKey)?.let{saved->title=saved.twText("title");detail=saved.twText("detail");criteria=saved.twText("criteria");effort=saved.twText("effortHours");due=saved.twText("dueDate");assignee=saved.twText("assigneeId").takeIf{it.isNotBlank()};dependencies=saved.twIds("dependsOnTaskIds");baseRevision=saved["expectedRevision"]?.jsonPrimitive?.int?:baseRevision;graphRevision=saved["expectedGraphRevision"]?.jsonPrimitive?.int?:graphRevision};loaded=true}catch(e:CancellationException){throw e}catch(e:Exception){persistenceError="本机草稿读取失败：${e.message}。请先备份，当前不会覆盖旧草稿。"}}
 LaunchedEffect(loaded,title,detail,criteria,effort,due,assignee,dependencies,baseRevision,graphRevision){if(loaded)draftStore.scheduleSave(draftKey,buildJsonObject{put("title",title);put("detail",detail);put("criteria",criteria);put("effortHours",effort);put("dueDate",due);put("assigneeId",assignee?.let{JsonPrimitive(it)}?:JsonNull);put("dependsOnTaskIds",JsonArray(dependencies.map{JsonPrimitive(it)}));put("expectedRevision",baseRevision);put("expectedGraphRevision",graphRevision)},onFailure={persistenceError="草稿未能保存到本机：${it.message}"})}
 persistenceError?.let{Text(it,color=MaterialTheme.colorScheme.error)}
 val outdated=if(task==null)graphRevision!=graph["graphRevision"]!!.jsonPrimitive.int else baseRevision!=twRevision(task)
 if(outdated){Text("任务或依赖图版本已变化，当前编辑已保留。请核对最新内容。",color=MaterialTheme.colorScheme.error);TextButton({baseRevision=task?.let{twRevision(it)}?:1;graphRevision=graph["graphRevision"]!!.jsonPrimitive.int}){Text("已核对版本，保留当前编辑")}}
 Text(if(task==null)"新建任务"else"任务设置",style=MaterialTheme.typography.titleLarge)
 TaskWorkspaceField("任务名称",title,{title=it},200);TaskWorkspaceField("任务说明",detail,{detail=it},4000,3);TaskWorkspaceField("验收标准",criteria,{criteria=it},4000,3);TaskWorkspaceField("预计投入（小时，0.25–200）",effort,{effort=it},8);TaskWorkspaceField("截止日期（YYYY-MM-DD，留空表示未知）",due,{due=it},10)
 if(task==null){Text("任务负责人");TaskWorkspaceMemberPicker(members,assignee){assignee=it};Text("前置任务");graph.twRows().forEach{row->val id=row.twText("taskId");Row{Checkbox(id in dependencies,{checked->dependencies=if(checked)dependencies+id else dependencies-id});Text(row.twText("title"),Modifier.padding(top=12.dp))}}}
 val hours=effort.toDoubleOrNull();val valid=title.isNotBlank()&&criteria.isNotBlank()&&hours!=null&&hours in .25..200.0&&(due.isBlank()||runCatching{java.time.LocalDate.parse(due)}.isSuccess)
 val body=buildJsonObject{if(task!=null)put("expectedRevision",baseRevision);put("title",title.trim());put("detail",detail.trim());put("criteria",criteria.trim());put("effortHours",hours?:1.0);put("dueDate",if(due.isBlank())JsonNull else JsonPrimitive(due));put("duePrecision",if(due.isBlank())"unknown"else"date");if(task==null){put("assigneeId",assignee?.let{JsonPrimitive(it)}?:JsonNull);put("dependsOnTaskIds",JsonArray(dependencies.map{JsonPrimitive(it)}));put("expectedGraphRevision",graphRevision)}}
 TaskWorkspaceAction(repository,if(task==null)"创建任务"else"保存任务内容",if(task==null)"$base/tasks"else"$base/tasks/${Uri.encode(identity)}",body,if(task==null)"POST"else"PATCH",valid&&loaded&&!outdated,onSuccess={saved->draftStore.remove(draftKey);baseRevision=saved["revision"]?.jsonPrimitive?.int?:baseRevision;onSaved()})
 if(task!=null){Text("分工与依赖分别保存，服务端会校验最新版本与依赖环。",style=MaterialTheme.typography.bodySmall)}
}

@Composable private fun TaskWorkspaceDetail(repository:ClientRepository,project:String,id:String,graph:JsonObject?,me:JsonObject?,members:List<JsonObject>,refresh:Int,onChanged:()->Unit){
 val base=twBase(project);val path="$base/tasks/${Uri.encode(id)}";var task by remember(id){mutableStateOf<JsonObject?>(null)};var error by remember{mutableStateOf<String?>(null)};var tab by rememberSaveable(id){mutableStateOf("work")}
 LaunchedEffect(id,refresh,repository.accountId){try{task=repository.get(path);error=null}catch(e:CancellationException){throw e}catch(e:Exception){error=e.message}}
 error?.let{Text(it,color=MaterialTheme.colorScheme.error)};val row=task?:return
 Text(row.twText("title"),style=MaterialTheme.typography.titleLarge);Text(twState(row));NativeMarkdown(row.twText("detail"));Text("验收标准",style=MaterialTheme.typography.titleMedium);NativeMarkdown(row.twText("criteria"));Text("预计投入：${row.twText("effortHours")} 小时");if(row.twText("dueDate").isNotEmpty())Text("期限：${row.twText("dueDate")}");TaskWorkspaceDependencies(row,graph?.twRows().orEmpty())
 TaskWorkspaceChoice("查看",listOf("work" to "执行与提交","settings" to "任务设置","history" to "提交验收历史","comments" to "讨论","inquiries" to "私密问询","assistance" to "AI 辅助计划"),tab){tab=it}
 val manage=me?.twCan("taskManage")==true;val revisionBody=buildJsonObject{put("expectedRevision",twRevision(row))}
 when(tab){
 "settings"->if(manage&&graph!=null){TaskWorkspaceEditor(repository,base,row,graph,members,onChanged);TaskWorkspaceAssignment(repository,path,row,members,onChanged);TaskWorkspaceDependencyEditor(repository,path,row,graph,onChanged);if(row.twText("lifecycleState")=="accepted"){var reason by rememberSaveable(id){mutableStateOf("")};TaskWorkspaceField("重新开启理由",reason,{reason=it},4000,2);TaskWorkspaceAction(repository,"重新开启任务","$base/collaboration/tasks/${Uri.encode(id)}/reopen",buildJsonObject{put("expectedRevision",twRevision(row));put("feedback",reason.trim())},enabled=reason.isNotBlank(),confirmation="重新开启后需要再次提交和验收，历史记录会保留。",onSuccess={onChanged()})}}else Text("只有具有任务管理权限的成员可以更改设置。")
 "inquiries"->TaskInquiriesScreen(repository,project,id)
 "comments"->TaskWorkspaceComments(repository,base,id)
 "history"->TaskWorkspaceSubmissions(repository,base,row,manage,refresh,onChanged)
 "assistance"->{TaskWorkspaceAssistance(repository,base,row);TaskWorkspacePrompt(repository,base,row) /* TaskBridgeWorkspace is attached by integration owner. */ }
 else->{var filesBusy by remember{mutableStateOf(false)};var filesRefresh by remember{mutableIntStateOf(0)};if(row.twText("assigneeId").isBlank()&&row.twText("lifecycleState")=="open")TaskWorkspaceAction(repository,"领取任务","$path/claim",revisionBody,onSuccess={onChanged()});val canSubmit=row.twText("assigneeId")==repository.accountId&&row.twText("lifecycleState") in listOf("in_progress","improve","rework");TaskWorkspaceFiles(repository,project,id,canSubmit,{filesBusy=it},{filesRefresh++});if(canSubmit)TaskWorkspaceSubmit(repository,base,row,filesBusy,filesRefresh,onChanged);TaskWorkspaceSubmissions(repository,base,row,manage,refresh,onChanged)}
 }
}
@Composable private fun TaskWorkspaceAssignment(repository:ClientRepository,path:String,task:JsonObject,members:List<JsonObject>,onChanged:()->Unit){
 var selected by rememberSaveable(task.twText("taskId")){mutableStateOf(task.twText("assigneeId").takeIf{it.isNotBlank()})};var reason by rememberSaveable{mutableStateOf("")};Text("调整负责人",style=MaterialTheme.typography.titleMedium);TaskWorkspaceMemberPicker(members,selected){selected=it};TaskWorkspaceField("分工理由",reason,{reason=it},2000,2)
 var assignmentRevision by rememberSaveable(task.twText("taskId")){mutableIntStateOf(twRevision(task))};if(assignmentRevision!=twRevision(task)){Text("任务已变化，请核对当前分工。");TextButton({assignmentRevision=twRevision(task)}){Text("已核对分工，保留编辑")}}
 TaskWorkspaceAction(repository,"保存分工","$path/assign",buildJsonObject{put("expectedRevision",assignmentRevision);put("assigneeId",selected?.let{JsonPrimitive(it)}?:JsonNull);put("reason",reason.trim())},enabled=reason.isNotBlank()&&assignmentRevision==twRevision(task),onSuccess={assignmentRevision=it["revision"]?.jsonPrimitive?.int?:assignmentRevision;reason="";onChanged()})
}
@Composable private fun TaskWorkspaceDependencyEditor(repository:ClientRepository,path:String,task:JsonObject,graph:JsonObject,onChanged:()->Unit){
 var dependencyRevision by rememberSaveable(task.twText("taskId")){mutableIntStateOf(graph["graphRevision"]!!.jsonPrimitive.int)};var selected by remember(task.twText("taskId")){mutableStateOf(task.twIds("dependsOnTaskIds"))};if(dependencyRevision!=graph["graphRevision"]!!.jsonPrimitive.int){Text("依赖图已变化，请核对当前前置任务。");TextButton({dependencyRevision=graph["graphRevision"]!!.jsonPrimitive.int}){Text("已核对依赖图，保留选择")}};Text("编辑前置依赖",style=MaterialTheme.typography.titleMedium);graph.twRows().filter{it.twText("taskId")!=task.twText("taskId")}.forEach{row->val id=row.twText("taskId");Row{Checkbox(id in selected,{checked->selected=if(checked)selected+id else selected-id});Text(row.twText("title"),Modifier.padding(top=12.dp))}}
 TaskWorkspaceAction(repository,"保存前置依赖","$path/dependencies",buildJsonObject{put("expectedGraphRevision",dependencyRevision);put("dependsOnTaskIds",JsonArray(selected.map{JsonPrimitive(it)}))},"PUT",enabled=dependencyRevision==graph["graphRevision"]!!.jsonPrimitive.int,onSuccess={dependencyRevision=it["graphRevision"]?.jsonPrimitive?.int?:dependencyRevision;onChanged()})
}
@Composable private fun TaskWorkspaceComments(repository:ClientRepository,base:String,id:String){var refresh by remember{mutableIntStateOf(0)};TaskWorkspacePage(repository,"$base/comments?targetType=task&targetId=${Uri.encode(id)}&limit=50",refresh){rows->rows.forEach{Text("${it.twText("authorName")} · ${it.twText("createdAt")}",style=MaterialTheme.typography.labelMedium);NativeMarkdown(it.twText("body"));HorizontalDivider()}};var body by rememberSaveable(id){mutableStateOf("")};TaskWorkspaceField("讨论内容",body,{body=it},4000,3);TaskWorkspaceAction(repository,"发表评论","$base/comments",buildJsonObject{put("targetType","task");put("targetId",id);put("body",body.trim())},enabled=body.isNotBlank(),onSuccess={body="";refresh++})}
@Composable private fun TaskWorkspaceSubmit(repository:ClientRepository,base:String,task:JsonObject,filesBusy:Boolean,filesRefresh:Int,onChanged:()->Unit){
 val draftKey="task-submission:${repository.accountId}:${task.twText("taskId")}";val restored=remember(draftKey){runCatching{repository.secrets.get(draftKey)?.let{repository.json.parseToJsonElement(it).jsonObject}}};var body by rememberSaveable(draftKey){mutableStateOf(restored.getOrNull()?.twText("body").orEmpty())};var baseRevision by rememberSaveable(draftKey){mutableIntStateOf(restored.getOrNull()?.get("expectedRevision")?.jsonPrimitive?.int?:twRevision(task))};var persistenceError by remember{mutableStateOf(restored.exceptionOrNull()?.let{"本机草稿无法读取，请先备份并检查存储：${it.message}"})};var files by remember{mutableStateOf<List<JsonObject>>(emptyList())};var fileError by remember{mutableStateOf<String?>(null)}
 LaunchedEffect(task.twText("taskId"),task.twText("revision"),filesRefresh){try{files=taskWorkspaceAllPages(repository,"$base/tasks/${Uri.encode(task.twText("taskId"))}/files").filter{it.twText("archivedAt").isBlank()&&it.twText("materialArchivedAt").isBlank()&&it.twText("deletedAt").isBlank()};fileError=null}catch(e:CancellationException){throw e}catch(e:Exception){fileError=e.message}}
 Text("提交本轮成果",style=MaterialTheme.typography.titleMedium);TaskWorkspaceField("成果说明（已加密保存在当前账户的本机草稿）",body,{body=it;try{repository.secrets.put(draftKey,buildJsonObject{put("body",it);put("expectedRevision",baseRevision)}.toString());persistenceError=null}catch(e:Exception){persistenceError="当前输入尚未保存到本机：${e.message}"}},12000,4)
 if(baseRevision!=twRevision(task)){Text("任务已更新，当前草稿保留。请核对新的验收标准。",color=MaterialTheme.colorScheme.error);TextButton({baseRevision=twRevision(task)}){Text("已核对标准，保留草稿继续")}}
 persistenceError?.let{Text(it,color=MaterialTheme.colorScheme.error)};fileError?.let{Text(it,color=MaterialTheme.colorScheme.error)};Text("本轮将固定引用 ${files.size} 个有效成果文件版本（上限 10 个）。")
 TaskWorkspaceAction(repository,"提交本轮成果","$base/tasks/${Uri.encode(task.twText("taskId"))}/submissions",buildJsonObject{put("expectedRevision",baseRevision);put("body",body.trim());put("materialVersionIds",JsonArray(files.map{it["versionId"]!!}))},enabled=body.isNotBlank()&&baseRevision==twRevision(task)&&fileError==null&&files.size<=10&&!filesBusy,confirmation="提交后将保存当前成果文件的固定版本；项目启用 AI 时可能自动触发评价。",prepare={draft->require(restored.isSuccess){"本机草稿读取失败，请先备份后处理"};kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO){repository.secrets.put(draftKey,draft.toString())};val active=taskWorkspaceAllPages(repository,"$base/tasks/${Uri.encode(task.twText("taskId"))}/files",networkOnly=true).filter{it.twText("archivedAt").isBlank()&&it.twText("materialArchivedAt").isBlank()&&it.twText("deletedAt").isBlank()};require(active.size<=10){"当前成果文件已超过 10 个，请刷新并归档不参与本轮的文件"};JsonObject(draft+("materialVersionIds" to JsonArray(active.map{it["versionId"]!!})))},onSuccess={body="";repository.secrets.put(draftKey,null);onChanged()})
}
internal suspend fun taskWorkspaceAllPages(repository:ClientRepository,path:String,networkOnly:Boolean=false):List<JsonObject>{val all=mutableListOf<JsonObject>();var cursor:String?=null;val seen=mutableSetOf<String>();do{val url=path+"?limit=100"+(cursor?.let{"&cursor=${Uri.encode(it)}"}?:"");val page=if(networkOnly)repository.networkJson("GET",url)else repository.get(url);all+=page.twRows();cursor=page.twText("nextCursor").takeIf{it.isNotBlank()};check(cursor==null||seen.add(cursor)){"分页游标重复"}}while(cursor!=null);return all}
@Composable private fun TaskWorkspaceSubmissions(repository:ClientRepository,base:String,task:JsonObject,manage:Boolean,refresh:Int,onChanged:()->Unit){
 Text("提交与验收历史",style=MaterialTheme.typography.titleMedium)
 TaskWorkspacePage(repository,"$base/tasks/${Uri.encode(task.twText("taskId"))}/submissions?limit=50",refresh){rows->if(rows.isEmpty())Text("尚无提交记录");rows.forEach{row->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("第 ${row.twText("round")} 轮 · ${row.twText("createdAt")}");NativeMarkdown(row.twText("body"));Text("本轮验收标准");NativeMarkdown(row.twText("criteria"));Text("验收结论：${mapOf("accept" to "通过","improve" to "改进","rework" to "重做")[row.twText("decision")]?:"待验收"}");NativeMarkdown(row.twText("feedback"));if(row["aiReport"]!=null){Text("AI 辅助报告（需要核验）");TaskWorkspaceNamedValues(row["aiReport"])};if(row.twText("evaluationError").isNotBlank())Text(row.twText("evaluationError"),color=MaterialTheme.colorScheme.error)
 row.twRows("materialVersions").forEach{version->TaskWorkspaceFixedVersion(repository,base,version)};TaskWorkspaceScores(repository,base,row,manage,onChanged)
 if(manage&&row.twText("submissionId")==task.twText("currentSubmissionId")){var decisionRevision by rememberSaveable(row.twText("submissionId")){mutableIntStateOf(twRevision(row))};var decision by rememberSaveable(row.twText("submissionId")){mutableStateOf("accept")};var feedback by rememberSaveable(row.twText("submissionId")){mutableStateOf("")};TaskWorkspaceChoice("人工验收",listOf("accept" to "通过","improve" to "需改进","rework" to "需重做"),decision){decision=it};TaskWorkspaceField("验收理由",feedback,{feedback=it},4000,3);TaskWorkspaceAction(repository,"提交人工验收","$base/collaboration/submissions/${Uri.encode(row.twText("submissionId"))}/decide",buildJsonObject{put("expectedRevision",decisionRevision);put("decision",decision);put("feedback",feedback.trim())},enabled=feedback.isNotBlank()&&decisionRevision==twRevision(row),confirmation="本轮成果将按所选结论处理，历史记录会保留。",onSuccess={decisionRevision=it["revision"]?.jsonPrimitive?.int?:decisionRevision;onChanged()});if(decisionRevision!=twRevision(row)){Text("本轮评价已变化，请核对后再提交。");TextButton({decisionRevision=twRevision(row)}){Text("已核对评价，保留验收理由")}}}
